code.java:
class Solution {
    public int getXORSum(int[] arr1,int[] arr2){
        int first=0,second=0;
        for(int value:arr1)first^=value;
        for(int value:arr2)second^=value;
        return first&second;
    }
}

code.kotlin:
class Solution {
    fun getXORSum(arr1:IntArray,arr2:IntArray):Int=arr1.fold(0){
        a,v->a xor v
    } and arr2.fold(0){
        a,v->a xor v
    }
}

code.cpp:
class Solution {
    public: int getXORSum(vector<int>& arr1,vector<int>& arr2){
        int first=accumulate(arr1.begin(),arr1.end(),0,bit_xor<int>()),second=accumulate(arr2.begin(),arr2.end(),0,bit_xor<int>());
        return first&second;
    }
};
